     2→namespace App\Services;
     3→
     4→use App\Core\Database;
     5→
     6→/**
     7→ * Service = business logica (import), los van HTTP.
     8→ *
     9→ * In controllers moet je liefst geen CSV parsing doen.
    10→ * Controllers: input lezen -> service aanroepen -> response sturen.
    11→ */
    12→class TikTokCsvImporter {
    13→    private $db;
    14→    public function __construct(Database $db) {
    15→        $this->db = $db;
    16→    }
    17→
    18→    private function normalizeHeader(array $header): array {
    19→        $out = [];
    20→        foreach ($header as $h) {
    21→            $k = strtolower(trim((string)$h));
    22→            $k = preg_replace('/\s+/', '_', $k);
    23→            $out[] = $k;
    24→        }
    25→        return $out;
    26→    }
    27→
    28→    private function v($x): ?string {
    29→        if ($x === null) return null;
    30→        $x = trim((string)$x);
    31→        return $x === '' ? null : $x;
    32→    }
    33→
    34→    /**
    35→     * Verwacht $_FILES['file'] input.
    36→     * Doet:
    37→     * - header detectie
    38→     * - upsert in posts
    39→     * - snapshot insert in metrics_history
    40→     * - log in import_history
    41→     */
    42→    public function import(array $file): array {
    43→        if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
    44→            return ['processed' => 0, 'skipped' => 0, 'error' => 'Upload mislukt'];
    45→        }
    46→
    47→        $tmp = $file['tmp_name'];
    48→        $processed = 0;
    49→        $skipped = 0;
    50→
    51→        $conn = $this->db->conn();
    52→        $conn->begin_transaction();
    53→
    54→        try {
    55→            $postsUpsert = $conn->prepare("
    56→                INSERT INTO posts (platform, platform_post_id, post_url, caption, posted_date, posted_time, views, likes, comments, shares)
    57→                VALUES ('tiktok', ?, ?, ?, ?, ?, ?, ?, ?, ?)
    58→                ON DUPLICATE KEY UPDATE
    59→                    post_url = VALUES(post_url),
    60→                    caption = VALUES(caption),
    61→                    posted_date = VALUES(posted_date),
    62→                    posted_time = VALUES(posted_time),
    63→                    views = VALUES(views),
    64→                    likes = VALUES(likes),
    65→                    comments = VALUES(comments),
    66→                    shares = VALUES(shares)
    67→            ");
    68→
    69→            $getPostId = $conn->prepare("SELECT id FROM posts WHERE platform='tiktok' AND platform_post_id=? LIMIT 1");
    70→            $mhInsert = $conn->prepare("
    71→                INSERT INTO metrics_history (post_id, views, likes, comments, shares, saves, snapshot_date)
    72→                VALUES (?, ?, ?, ?, ?, ?, ?)
    73→            ");
    74→
    75→            if (($fh = fopen($tmp, 'r')) === false) {
    76→                throw new \RuntimeException('Kan CSV niet openen');
    77→            }
    78→
    79→            $header = fgetcsv($fh);
    80→            if (!$header) throw new \RuntimeException('Lege CSV');
    81→            $header = $this->normalizeHeader($header);
    82→
    83→            while (($row = fgetcsv($fh)) !== false) {
    84→                $rec = array_combine($header, $row);
    85→
    86→                // Flexibele keys: pas aan naar je exacte export indien nodig
    87→                $ppid = $this->v($rec['post_id'] ?? $rec['video_id'] ?? $rec['id'] ?? null);
    88→                if (!$ppid) { $skipped++; continue; }
    89→
    90→                $caption = $this->v($rec['caption'] ?? $rec['title'] ?? null);
    91→                $url = $this->v($rec['url'] ?? $rec['link'] ?? null);
    92→                $date = $this->v($rec['posted_date'] ?? $rec['date'] ?? $rec['published_date'] ?? null);
    93→                $time = $this->v($rec['posted_time'] ?? $rec['time'] ?? null);
    94→
    95→                $views = (int)($rec['views'] ?? $rec['play_count'] ?? 0);
    96→                $likes = (int)($rec['likes'] ?? $rec['like_count'] ?? 0);
    97→                $comments = (int)($rec['comments'] ?? $rec['comment_count'] ?? 0);
    98→                $shares = (int)($rec['shares'] ?? $rec['share_count'] ?? 0);
    99→                $saves = (int)($rec['saves'] ?? $rec['save_count'] ?? 0);
   100→                $snapshot = $this->v($rec['snapshot_date'] ?? date('Y-m-d'));
   101→
   102→                // posts upsert
   103→                $postsUpsert->bind_param("sssssiiii", $ppid, $url, $caption, $date, $time, $views, $likes, $comments, $shares);
   104→                $postsUpsert->execute();
   105→
   106→                // find post_id
   107→                $getPostId->bind_param("s", $ppid);
   108→                $getPostId->execute();
   109→                $res = $getPostId->get_result();
   110→                $pidRow = $res ? $res->fetch_assoc() : null;
   111→                $pid = $pidRow ? (int)$pidRow['id'] : 0;
   112→
   113→                if ($pid) {
   114→                    $mhInsert->bind_param("iiiiiis", $pid, $views, $likes, $comments, $shares, $saves, $snapshot);
   115→                    $mhInsert->execute();
   116→                }
   117→
   118→                $processed++;
   119→            }
   120→
   121→            fclose($fh);
   122→
   123→            // import_history
   124→            $fn = $file['name'] ?? 'upload.csv';
   125→            $imp = $conn->prepare("
   126→                INSERT INTO import_history (filename, platform, import_type, rows_imported, rows_skipped, imported_at)
   127→                VALUES (?, 'tiktok', 'csv', ?, ?, NOW())
   128→            ");
   129→            $imp->bind_param("sii", $fn, $processed, $skipped);
   130→            $imp->execute();
   131→
   132→            $conn->commit();
   133→            return ['processed' => $processed, 'skipped' => $skipped];
   134→        } catch (\Throwable $e) {
   135→            $conn->rollback();
   136→            return ['processed' => $processed, 'skipped' => $skipped, 'error' => $e->getMessage()];
   137→        }
   138→    }
   139→}
